addIntro.source:
function () {
            _super.prototype.execute.call(this);
            var bonusAwarded = false;
            if (this._server.getLogicResponse().reelSpinData.length > 0)
                bonusAwarded = this._server.getLogicResponse().reelSpinData[0].bonusAwarded;
            bonusAwarded = bonusAwarded || sgigame.HandleIncompleteGameCmd.IS_FREESPIN_RECOVERY || sgigame.HandleIncompleteGameCmd.IS_FEATURE_SELECTION_RECOVERY;
            bonusAwarded = bonusAwarded || sgigame.HistoryModel.HANDLE_TRANSITION_LOGIC_HISTORY;
            if (sgigame.HistoryModel.HANDLE_TRANSITION_LOGIC_HISTORY)
                sgigame.HistoryModel.HANDLE_TRANSITION_LOGIC_HISTORY = false;
            this._transitionView.init(bonusAwarded);
            this._subgamesModel.fsTransitionLayer = this._fsTransitionLayer;
            this.eventDispatcher.dispatchEvent(new dragonwings.MediatorEvent(dragonwings.MediatorEvent.ADDED_TO_STAGE, this._fsTransitionLayer));
            this._subgamesModel.fsTransitionLayer.addChild(this._transitionView);
            this._eventDispatcher.dispatchEvent(new dragonwings.MediatorEvent(dragonwings.MediatorEvent.ADDED_TO_STAGE, this._transitionView));
            if (!sgigame.HandleIncompleteGameCmd.IS_FREESPIN_RECOVERY) {
                if (bonusAwarded) {
                    this._subgamesModel.activateViews([
                        this._subgamesModel.fsSelectionLayer,
                        this._subgamesModel.jackpotMeterLayer,
                        this._subgamesModel.fsTransitionLayer
                    ]);
                }
                else {
                    this._subgamesModel.activateViews([
                        this._subgamesModel.freeSpinLayer,
                        this._subgamesModel.jackpotMeterLayer,
                        this._subgamesModel.fsTransitionLayer
                    ]);
                }
                this._transitionView.startTransition();
            }
        }

mediatorComplete.source:
function () {
            var _this = this;
            this._transitionView.removeEventListener(sgigame.TransitionEvent.TRANSITION_COMPLETE, this.onTransitionComplete, this);
            if (this._transitionView.isIntro) {
                TweenLite.delayedCall(1.0, function () {
                    _this._gameContextEventDispatcher.dispatchEvent(new sgigame.TransitionEvent(sgigame.TransitionEvent.INTRO_TRANSITION_COMPLETE));
                });
            }
            else {
                this._gameContextEventDispatcher.dispatchEvent(new sgigame.TransitionEvent(sgigame.TransitionEvent.OUTRO_TRANSITION_COMPLETE));
                this._subgamesModel.activateViews([
                    this._subgamesModel.basegameBgLayer,
                    this._subgamesModel.jackpotMeterLayer,
                    this._subgamesModel.reelsLayer,
                    this._subgamesModel.bigWinLayer
                ]);
            }
            if (this._transitionView.parent) {
                this._transitionView.parent.removeChild(this._transitionView);
            }
        }

viewInit.source:
function (isIntro) {
            this._isIntro = isIntro;
            if (!isIntro) {
                if (this.checkWinThreshold()) {
                    this._toShowPlacard = true;
                    this._outroPlacard.init();
                    this.addChild(this._outroPlacard);
                    this._eventDispatcher.dispatchEvent(new dragonwings.MediatorEvent(dragonwings.MediatorEvent.ADDED_TO_STAGE, this._outroPlacard));
                    this._outroPlacard.addEventListener(sgigame.TransitionEvent.OUTRO_PLACARD_DISPLAY_COMPLETE, this.playTransitionAnim, this);
                }
                else {
                    this._toShowPlacard = false;
                }
                this.addTransition();
            }
            else {
                this.addTransition();
            }
            this.onOrientationChange();
        }

viewStart.source:
function () {
            if (this._isIntro) {
                this._audioModel.stopFeatureSelectionLoop();
                this.playTransitionAnim();
            }
            else {
                if (this._toShowPlacard) {
                    this._audioModel.fadeOutFreeSpinsLoopSound();
                    this._audioModel.playFreespinEndSound();
                    this._outroPlacard.bangUpTotalWin(this._totalFSWin);
                }
                else {
                    this.playTransitionAnim();
                }
            }
        }

viewComplete.source:
function () {
            this._transitionAnim.stop();
            this._transitionAnim.visible = false;
            this._transitionAnim.removeEventListener(rendering.DisplayEvent.ANIMATION_COMPLETE, this.onAnimationComplete, this);
            this.dispatchEvent(new sgigame.TransitionEvent(sgigame.TransitionEvent.TRANSITION_COMPLETE));
            this._transitionAnim.removeEventListener(rendering.DisplayEvent.ENTER_FRAME, this.onEnterFrame, this);
            this._transitionAnim.removeEventListener(rendering.DisplayEvent.ANIMATION_COMPLETE, this.onAnimationComplete, this);
        }
